using System.Collections.Generic;using UnityEngine;using System.Linq;using static BotHelperFunctions;public class BottusMinimus : BotTemplate{public BottusMinimus(int botColor){color = botColor; name = "Bottus Minimus"; pieces = new List<Piece>(); choosePieces();}override
public NextMove nextMove(){List<NextMove> allMoves = getAllPossibleBotMovesAndAbilities(this, this.currentBoardState, this.color);NextMove move = allMoves[0];if (move.moveType == "move"){move.move.p = getOriginalPieceFromClone(move.move.p);}else{move.ability.piece = getOriginalPieceFromClone(move.ability.piece);}return move;}}